package com.clearchoice;

import java.math.BigDecimal;import java.util.*;import java.util.regex.*;
/** Deliberately narrow: visible, explicitly labelled amounts only. No retailer assumptions or inferred discounts. */
public final class PriceEvidenceParser {
 public static final class Line {public final String id,text;public final int left,top,right,bottom;public Line(String id,String text,int l,int t,int r,int b){this.id=id;this.text=text==null?"":text.trim();left=l;top=t;right=r;bottom=b;}boolean valid(){return !id.isEmpty()&&right>left&&bottom>top&&left>=0&&top>=0;}}
 public static final class Result {public final Line anchor;public final String currency,heading,detail,fingerprint;public final BigDecimal amount;public final boolean complete;Result(Line a,String c,BigDecimal n,boolean full,String h,List<String> parts,String warning){anchor=a;currency=c;amount=n;complete=full;heading=h+" · "+c+" "+n.toPlainString();detail=String.join("\n",parts)+(warning.isEmpty()?"":"\n"+warning);fingerprint=a.id+"|"+heading+"|"+detail+"|"+a.left+","+a.top+","+a.right+","+a.bottom;}}
 static final String C="(?:SGD|S\\$|USD|US\\$|MYR|RM|EUR|€|GBP|£)";static final Pattern MONEY=Pattern.compile("("+C+")\\s*([0-9]+(?:,[0-9]{3})*(?:\\.[0-9]{1,2})?)(?![0-9.,])|([0-9]+(?:,[0-9]{3})*(?:\\.[0-9]{1,2})?)\\s*(SGD|USD|MYR|EUR|GBP)\\b",Pattern.CASE_INSENSITIVE);
 static final Pattern BASE=Pattern.compile("^(?:item price|product price|subtotal|items subtotal|merchandise subtotal)\\s*[:：]?\\s*",Pattern.CASE_INSENSITIVE),TOTAL=Pattern.compile("^(?:grand total|order total|total)\\s*[:：]?\\s*",Pattern.CASE_INSENSITIVE),SHIPPING=Pattern.compile("^(?:delivery|shipping)(?: fee| cost)?\\s*[:：]?\\s*",Pattern.CASE_INSENSITIVE),FEE=Pattern.compile("^(?:mandatory fees?|service fee|handling fee|tax|taxes)\\s*[:：]?\\s*",Pattern.CASE_INSENSITIVE);
 static final class Money {String c;BigDecimal n;Money(String c,String n){this.c=currency(c);this.n=new BigDecimal(n.replace(",",""));}}
 static String currency(String c){c=c.toUpperCase(Locale.ROOT);return c.equals("S$")?"SGD":c.equals("US$")?"USD":c.equals("RM")?"MYR":c.equals("€")?"EUR":c.equals("£")?"GBP":c;}
 static boolean onlyMoney(String text){Matcher m=MONEY.matcher(text.trim());return m.matches();}
 static Money money(String text){Matcher m=MONEY.matcher(text);if(!m.find())return null;Money value=m.group(1)!=null?new Money(m.group(1),m.group(2)):new Money(m.group(4),m.group(3));return m.find()?null:value;}
 public static Result parse(List<Line> input){if(input==null||input.isEmpty()||input.size()>400)return null;List<Line> lines=new ArrayList<>();Set<String> ids=new HashSet<>();for(Line l:input){if(l==null||!l.valid()||!ids.add(l.id))return null;lines.add(l);}String all="";for(Line l:lines)all+=" "+l.text.toLowerCase(Locale.ROOT);if(Pattern.compile("select (?:a )?(?:variant|size|color|colour)|choose (?:options|variant|size|color|colour)|price range|starting (?:at|from)|\\bfrom\\s+(?:sgd|s\\$|usd)").matcher(all).find())return null;
 String cur=null;List<Line> bases=new ArrayList<>(),totals=new ArrayList<>(),shipping=new ArrayList<>(),fees=new ArrayList<>();List<String> parts=new ArrayList<>();boolean unresolvedFee=false,unresolvedDelivery=false;boolean inclusive=all.contains("including delivery and all mandatory fees")||all.contains("delivery, taxes and fees included"),taxAndFees=all.contains("taxes and all mandatory fees included");
 for(Line l:lines){Money m=money(l.text);if(SHIPPING.matcher(l.text).find()){String rest=SHIPPING.matcher(l.text).replaceFirst("").trim();if(!onlyMoney(rest)&&!rest.equalsIgnoreCase("free")&&!rest.equalsIgnoreCase("included"))unresolvedDelivery=true;}if(FEE.matcher(l.text).find()&&m==null&&!l.text.equalsIgnoreCase("Taxes and all mandatory fees included"))unresolvedFee=true;if(m!=null){if(cur!=null&&!cur.equals(m.c))return null;cur=m.c;if(BASE.matcher(l.text).find()){if(!onlyMoney(BASE.matcher(l.text).replaceFirst("")))return null;bases.add(l);}else if(TOTAL.matcher(l.text).find())totals.add(l);else if(SHIPPING.matcher(l.text).find())shipping.add(l);else if(FEE.matcher(l.text).find()){if(!onlyMoney(FEE.matcher(l.text).replaceFirst("")))return null;fees.add(l);}else return null;}else if(MONEY.matcher(l.text).find()||l.text.matches(".*(?:\\$|SGD|USD|MYR|EUR|GBP).*\\d.*"))return null;else if(SHIPPING.matcher(l.text).find())shipping.add(l);}
 if(inclusive&&(unresolvedFee||unresolvedDelivery))return null;
 if(totals.size()==1&&inclusive&&bases.size()<=1){Line total=totals.get(0);Money n=money(total.text);if(n==null)return null;parts.add("Observed inclusive total: "+total.text);return new Result(total,n.c,n.n,true,"Observed total",parts,"Source explicitly includes delivery and mandatory fees; no amounts added again.");}
 if(bases.size()!=1||!totals.isEmpty()||shipping.size()>1)return null;Line base=bases.get(0);Money n=money(base.text);boolean subtotal=base.text.toLowerCase(Locale.ROOT).contains("subtotal");Matcher qty=Pattern.compile("\\b(?:qty|quantity)\\s*[:x]?\\s*(\\d+)").matcher(all);int quantity=-1;while(qty.find()){int q;try{q=Integer.parseInt(qty.group(1));}catch(NumberFormatException e){return null;}if(q<1)return null;if(quantity!=-1&&quantity!=q)return null;quantity=q;}if(!subtotal&&quantity>1)return null;
 BigDecimal sum=n.n;parts.add("Observed "+(subtotal?"subtotal":"item price")+": "+n.c+" "+n.n.toPlainString());boolean deliveryKnown=false;
 for(Line line:shipping){String rest=SHIPPING.matcher(line.text).replaceFirst("").trim();Money cost=money(rest);if(cost!=null&&rest.matches("(?i)(?:"+C+")\\s*[0-9,]+(?:\\.[0-9]{1,2})?|[0-9,]+(?:\\.[0-9]{1,2})?\\s*(?:SGD|USD|MYR|EUR|GBP)")){sum=sum.add(cost.n);deliveryKnown=true;parts.add("Observed delivery: "+cost.c+" "+cost.n.toPlainString());}else if(rest.equalsIgnoreCase("free")||rest.equalsIgnoreCase("included")){deliveryKnown=true;parts.add("Observed delivery: "+rest);} }
 if(taxAndFees&&!fees.isEmpty())return null;if(fees.size()>1)for(Line line:fees)if(line.text.toLowerCase(Locale.ROOT).startsWith("mandatory"))return null;
 Set<String> feeKinds=new HashSet<>();for(Line line:fees){String kind=FEE.matcher(line.text).replaceAll("");String label=line.text.substring(0,line.text.length()-kind.length()).toLowerCase(Locale.ROOT);if(!feeKinds.add(label))return null;Money cost=money(line.text);sum=sum.add(cost.n);parts.add("Observed fee: "+line.text);}
 boolean complete=!unresolvedFee&&!unresolvedDelivery&&deliveryKnown&&taxAndFees&&(subtotal||quantity==1);String warning=!deliveryKnown?"Delivery not available · amount incomplete":!complete?"Additional charges and eligibility not verified · amount incomplete":"Delivery and all mandatory fees explicitly accounted for in visible source.";
 return new Result(base,n.c,sum,complete,complete?"Observed total":subtotal?"Observed subtotal + known fees":"Observed item + known fees",parts,warning);
 }
 /** Callers must clear before observing a different revision, even if the new parse fails. */
 public static final class Current {String revision;Result result;public void update(String rev,Result r){revision=rev;result=r;}public Result get(String rev){if(!Objects.equals(revision,rev)){clear();return null;}return result;}public void clear(){revision=null;result=null;}}
 private PriceEvidenceParser(){}
}
